package com.osrsjokes;

import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/** Unchanged attachments generated by the collector's authenticated export route. */
public class CollectorImportTest
{
	static String fixture(String name) throws IOException
	{
		try (InputStream input = CollectorImportTest.class.getResourceAsStream("/collector/" + name))
		{
			assertNotNull("Missing collector fixture: " + name, input);
			return new String(input.readAllBytes(), StandardCharsets.UTF_8);
		}
	}

	@Test
	public void importsDeckNamesOrderAndExactJokeTextWithoutConversion() throws IOException
	{
		List<DeckDefinition> decks = DeckCodec.deserialize(fixture("decks.json"));
		assertEquals(2, decks.size());
		DeckDefinition empty = decks.get(0);
		assertEquals("10000000-0000-4000-8000-000000000001", empty.getId());
		assertEquals("Empty deck", empty.getName());
		assertTrue(empty.getJokes().isEmpty());
		assertTrue(new JokeDeck(empty.getJokes()).draw().startsWith("No jokes yet."));

		DeckDefinition populated = decks.get(1);
		assertEquals("10000000-0000-4000-8000-000000000002", populated.getId());
		assertEquals("Gielinor \"jokes\" \\ 🦀", populated.getName());
		List<String> expected = List.of(
			"The Wise Old Man said \"bank it\". Path: C:\\Gielinor\\bank.",
			"Why did the crab cross the shore?\n\nTo say 你好, café! 🦀\nThen scuttle away.",
			"Keep // this and /* that */ as text.\r\nNext line\twith a tab.\n\nA blank line stays.");
		assertEquals(expected, populated.getJokes());
		String[] parts = populated.getJokes().get(1).split("\n\n", 2);
		assertEquals(2, parts.length);
		assertEquals("Why did the crab cross the shore?", parts[0]);
		assertEquals("To say 你好, café! 🦀\nThen scuttle away.", parts[1]);

		JokeDeck draw = new JokeDeck(populated.getJokes());
		for (String text : expected)
		{
			assertEquals(text, draw.draw());
		}
		assertEquals(expected.get(0), draw.draw());
	}

	@Test
	public void importsOneDeckWithTheSameIdentityAndContents() throws IOException
	{
		List<DeckDefinition> single = DeckCodec.deserialize(fixture("one-deck.json"));
		assertEquals(1, single.size());
		DeckDefinition multiple = DeckCodec.deserialize(fixture("decks.json")).get(1);
		assertEquals(multiple.getId(), single.get(0).getId());
		assertEquals(multiple.getName(), single.get(0).getName());
		assertEquals(multiple.getJokes(), single.get(0).getJokes());
	}

	@Test
	public void renamedExportRetainsSelectedIdentityWhenDeckOrderChanges() throws IOException
	{
		List<DeckDefinition> original = DeckCodec.deserialize(fixture("decks.json"));
		List<DeckDefinition> renamed = DeckCodec.deserialize(fixture("renamed-decks.json"));
		DeckDefinition selected = original.get(1);
		assertEquals(2, renamed.size());
		assertEquals(selected.getId(), renamed.get(0).getId());
		assertEquals("A renamed deck", renamed.get(0).getName());
		assertEquals(selected.getJokes(), renamed.get(0).getJokes());
		assertEquals(original.get(0).getId(), renamed.get(1).getId());
		assertEquals(original.get(0).getName(), renamed.get(1).getName());
		assertTrue(renamed.get(1).getJokes().isEmpty());
	}
}
